const rawTicket = $input.first().json;

const firstNonEmpty = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
};

const requesterEmail = firstNonEmpty(
  rawTicket.email,
  rawTicket.requester?.email,
  rawTicket.customer?.email,
  rawTicket.contact?.email,
  rawTicket.from
).toLowerCase();
const requesterName = firstNonEmpty(rawTicket.name, rawTicket.requester?.name, rawTicket.customer?.name, rawTicket.contact?.name, requesterEmail.split('@')[0]);
const subject = firstNonEmpty(rawTicket.subject, rawTicket.title, rawTicket.summary, 'No subject provided');
const message = firstNonEmpty(rawTicket.message, rawTicket.description, rawTicket.body, rawTicket.text);
const ticketId = firstNonEmpty(rawTicket.ticketId, rawTicket.id, rawTicket.external_id, rawTicket.conversationId, `incoming-${Date.now()}`);
const ticketUrl = firstNonEmpty(rawTicket.ticketUrl, rawTicket.url, rawTicket.html_url);
const sourceSystem = firstNonEmpty(rawTicket.source, rawTicket.helpdesk, rawTicket.system, 'webhook');
const companyName = firstNonEmpty(rawTicket.company, rawTicket.organization?.name, rawTicket.account?.name);
const domain = requesterEmail.includes('@') ? requesterEmail.split('@').pop() : '';
const normalizedSubject = subject.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 90);
const normalizedMessage = message.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 160);
const dedupeKey = [requesterEmail || 'unknown-email', normalizedSubject || normalizedMessage || ticketId].join('::');
const vipDomains = ['REPLACE_WITH_VIP_DOMAIN_1.com', 'REPLACE_WITH_VIP_DOMAIN_2.com'];
const vipDomain = vipDomains.includes(domain);
const missingFields = [];
if (!requesterEmail) missingFields.push('requester email');
if (!subject) missingFields.push('subject');
if (!message) missingFields.push('message/body');

return [{
  json: {
    receivedAt: new Date().toISOString(),
    sourceSystem,
    ticketId,
    ticketUrl,
    requesterEmail,
    requesterName,
    companyName,
    domain,
    subject,
    message,
    messagePreview: message.slice(0, 500),
    dedupeKey,
    vipDomain,
    defaultSlaMinutes: vipDomain ? 30 : 240,
    missingFields,
    hasMissingRequired: missingFields.length > 0,
    rawTicket,
  },
}];

