const ticket = $node["Normalize Ticket + SLA Profile"].json;
const hubspot = $node["Enrich Contact in HubSpot"].json || {};
const aiResponse = $input.first().json || {};

const safeParseJson = (content) => {
  if (!content || typeof content !== 'string') return null;
  const cleaned = content.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/i, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    return null;
  }
};

const content = aiResponse.choices?.[0]?.message?.content;
const parsed = safeParseJson(content);
const aiFailed = !parsed || Boolean(aiResponse.error);
const fallback = {
  category: 'general',
  priority: ticket.vipDomain ? 'p1' : 'p2',
  sentiment: 'confused',
  confidence: 0.45,
  internalSummary: `Manual review needed for ${ticket.subject}. AI triage was unavailable or returned invalid JSON.`,
  suggestedRoute: 'human_review',
  replySubject: `Re: ${ticket.subject}`,
  replyDraft: `Hi ${ticket.requesterName || 'there'},\n\nThanks for reaching out. We received your request and our team is reviewing it now. We'll follow up with the next step shortly.\n\nBest,\nSupport`,
  slaRiskReason: aiFailed ? 'AI request failed or produced invalid output.' : 'Fallback route selected.',
};
const triage = { ...fallback, ...(parsed || {}) };
const priority = String(triage.priority || fallback.priority).toLowerCase();
const category = String(triage.category || fallback.category).toLowerCase();
const sentiment = String(triage.sentiment || fallback.sentiment).toLowerCase();
const confidence = Number(triage.confidence || fallback.confidence);
const riskText = `${ticket.subject} ${ticket.message} ${triage.slaRiskReason || ''}`.toLowerCase();
const urgentKeywords = ['outage', 'down', 'breach', 'security', 'data loss', 'cannot login', 'production', 'payment failed', 'chargeback'];
const keywordEscalation = urgentKeywords.some((keyword) => riskText.includes(keyword));
const protectedCategory = ['security', 'billing'].includes(category);
const needsEscalation = ticket.vipDomain || ['p0', 'p1'].includes(priority) || sentiment === 'angry' || protectedCategory || keywordEscalation;
const needsHumanReview = aiFailed || confidence < 0.76 || triage.suggestedRoute === 'human_review' || needsEscalation;
const hubspotContact = Array.isArray(hubspot.results) && hubspot.results.length > 0 ? hubspot.results[0] : null;

return [{
  json: {
    ...ticket,
    hubspotFound: Boolean(hubspotContact),
    hubspotContactId: hubspotContact?.id || '',
    hubspotLifecycleStage: hubspotContact?.properties?.lifecyclestage || '',
    hubspotScore: hubspotContact?.properties?.hubspotscore || '',
    category,
    priority,
    sentiment,
    confidence,
    suggestedRoute: triage.suggestedRoute || fallback.suggestedRoute,
    internalSummary: triage.internalSummary || fallback.internalSummary,
    replySubject: triage.replySubject || fallback.replySubject,
    replyDraft: triage.replyDraft || fallback.replyDraft,
    slaRiskReason: triage.slaRiskReason || fallback.slaRiskReason,
    needsEscalation,
    needsHumanReview,
    aiFailed,
    routeDecision: needsEscalation ? 'urgent_escalation' : needsHumanReview ? 'human_review' : 'draft_ready',
  },
}];

